// Credentials live in n8n now (no tokens in webhook body).
// Connection state is derived from whether the upstream HTTP call succeeded.

const apollo = $('ApolloStats').first()?.json;
const apolloConnected = !!apollo && !apollo.error && !apollo.errors;
const emailsSent = apolloConnected ? (apollo.num_sent ?? apollo.emails_sent ?? null) : null;
const numOpens = apolloConnected ? (apollo.num_opens ?? apollo.opens ?? null) : null;
const numReplies = apolloConnected ? (apollo.num_replies ?? apollo.replies ?? null) : null;

const events = $('CalendlyEvents').first()?.json;
const calendlyConnected = !!events && Array.isArray(events.collection);
const meetingsBooked = calendlyConnected ? events.collection.length : null;

const openRate = (emailsSent && emailsSent > 0 && numOpens != null) ? (numOpens / emailsSent) * 100 : null;
const replyRate = (emailsSent && emailsSent > 0 && numReplies != null) ? (numReplies / emailsSent) * 100 : null;
const meetingConversion = (emailsSent && emailsSent > 0 && meetingsBooked != null) ? (meetingsBooked / emailsSent) * 100 : null;

let replySparkline = null;
if (apolloConnected && Array.isArray(apollo.daily_replies)) {
  replySparkline = apollo.daily_replies.slice(-14);
} else if (apolloConnected && Array.isArray(apollo.daily_stats)) {
  replySparkline = apollo.daily_stats.slice(-14).map(d => d.replies || 0);
}

return [{
  json: {
    emails_sent: emailsSent,
    open_rate_pct: openRate,
    reply_rate_pct: replyRate,
    reply_sparkline: replySparkline,
    meetings_booked: meetingsBooked,
    meeting_conversion_pct: meetingConversion,
    apollo_connected: apolloConnected,
    calendly_connected: calendlyConnected,
    period_label: 'Last 14 days'
  }
}];
